mapper.select:
select s.id,s.name,s.category_id,s.price,s.status,s.description,s.image,s.create_time,s.update_time,s.create_user,s.update_user,c.name as categoryName from setmeal s left join category c on s.category_id = c.id


        and s.name like CONCAT('%', #{name}, '%')


        and category_id = #{categoryId}


        and status = #{status}


order by create_time desc
